def priority(task, state):
    # Bottleneck-Aware Slack Time (BAST)
    # Uses slack time scaled by bottleneck pressure and remaining steps

    current_time = state['current_time']
    litho_congested = state['litho_queue'] > 5
    litho_util = state['litho_utilization']
    is_hot = task.priority.value == 4
    is_urgent = task.priority.value == 3

    # Calculate slack if deadline exists
    if task.deadline is not None:
        slack = task.deadline - current_time
    else:
        slack = 999999  # effectively infinite

    # Base: inverse of remaining processing time (SPT-like)
    remaining = task.estimated_remaining if task.estimated_remaining > 0 else 0.1
    base_score = 100.0 / remaining

    # Hot lot handling with deadline-driven urgency
    if is_hot:
        if task.deadline is not None:
            if slack < 0:
                # Already late: exponential urgency
                base_score = 1000000.0 * (1.0 + (-slack) * 10.0)
            elif slack < 10:
                # Within 10 hours: hyperbolic urgency
                base_score = 500000.0 / max(slack, 0.1)
            else:
                # Healthy slack: moderate boost
                base_score = 50000.0 + (20.0 - min(slack, 20.0)) * 5000.0
        else:
            base_score = 50000.0  # Hot without deadline
    elif is_urgent:
        base_score *= 15.0

    # Bottleneck awareness: next step litho check
    next_is_litho = (task.remaining_steps % 5 == 4)

    if litho_congested or litho_util > 0.85:
        if next_is_litho:
            if not is_hot:
                # Heavy penalty for sending to congested litho
                base_score *= 0.2
            else:
                # Hot lots still go but with reduced priority
                base_score *= 0.7
        else:
            # Boost non-litho steps to clear other machines
            base_score *= 2.0

    # Remaining steps penalty: prefer nearly-finished lots
    steps_remaining = task.remaining_steps
    if steps_remaining <= 5 and not is_hot:
        base_score *= 1.5  # Boost near-completion lots

    # FIFO tiebreaker for stability
    base_score += task.queue_wait_time * 0.01

    return base_score

